// subsite by tag rule (faq_subsite_tags). The two branches are disjoint in
// practice (native rows have source_id IS NULL; the import branch filters
// source_id IS NOT NULL), so UNION ALL is safe and cheaper than UNION.
// ---------------------------------------------------------------------------
func (q *Queries) CreateSubsite(ctx context.Context, arg CreateSubsiteParams) (FaqSubsites, error) {
	row := q.db.QueryRow(ctx, createSubsite, arg.Slug, arg.DisplayName, arg.Description)
	var i FaqSubsites
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.DisplayName,
		&i.Description,
		&i.CreatedAt,
	)
	return i, err
}

