// questions stay locked after restore; open stay open). Skips rows already
// deleted so prev_status isn't overwritten with 'deleted'.
func (q *Queries) DeleteQuestion(ctx context.Context, arg DeleteQuestionParams) error {
	_, err := q.db.Exec(ctx, deleteQuestion, arg.ClosedByUserID, arg.CloseReason, arg.ID)
	return err
}

