const isQuestionInSubsite = `-- name: IsQuestionInSubsite :one

SELECT EXISTS (
    SELECT 1 FROM faq_questions q
    WHERE q.id = $1 AND q.status <> 'deleted'
      AND (
            q.subsite_id = $2
            OR (q.source_id IS NOT NULL AND EXISTS (
                SELECT 1 FROM faq_question_tags qt
                JOIN faq_subsite_tags st ON st.tag_id = qt.tag_id
                WHERE qt.question_id = q.id AND st.subsite_id = $2
            ))
            OR EXISTS (
                SELECT 1 FROM faq_subsite_questions sq
                WHERE sq.question_id = q.id AND sq.subsite_id = $2
            )
          )
)::BOOLEAN AS in_subsite
`

type IsQuestionInSubsiteParams struct {
	QuestionID int64
	SubsiteID  *int64
}

// ---------------------------------------------------------------------------
// Subsite question-membership checks (route 404 + see-also)
// ---------------------------------------------------------------------------
// Returns 1 if @question_id is reachable from @subsite_id (native,
// tag-rule match, or explicit curation), 0 otherwise. Cheaper than
// re-running the full list query: handlers call this on every
// subsite-prefixed detail load to decide 404 vs. render.
func (q *Queries) IsQuestionInSubsite(ctx context.Context, arg IsQuestionInSubsiteParams) (bool, error) {
	row := q.db.QueryRow(ctx, isQuestionInSubsite, arg.QuestionID, arg.SubsiteID)
	var in_subsite bool
	err := row.Scan(&in_subsite)
	return in_subsite, err
}

const listAnswersForQuestion = `-- name: ListAnswersForQuestion :many
SELECT id, question_id, body_md, body_html, author_user_id, source_id, source_post_id, source_url, imported_author_id, imported_score, local_score, locally_modified, needs_review, created_at, updated_at, edited_at, last_editor_user_id, edit_count, (COALESCE(imported_score, 0) + local_score)::INTEGER AS total_score
FROM faq_answers
WHERE question_id = $1
ORDER BY total_score DESC, created_at ASC
`

type ListAnswersForQuestionRow struct {
	ID               int64
	QuestionID       int64
	BodyMd           string
	BodyHtml         string
	AuthorUserID     *int64
	SourceID         *int64
	SourcePostID     *int64
	SourceUrl        *string
	ImportedAuthorID *int64
	ImportedScore    *int32
	LocalScore       int32
	LocallyModified  bool
	NeedsReview      bool
	CreatedAt        pgtype.Timestamptz
	UpdatedAt        pgtype.Timestamptz
	EditedAt         pgtype.Timestamptz
	LastEditorUserID *int64
	EditCount        int32
	TotalScore       int32
}

func (q *Queries) ListAnswersForQuestion(ctx context.Context, questionID int64) ([]ListAnswersForQuestionRow, error) {
	rows, err := q.db.Query(ctx, listAnswersForQuestion, questionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListAnswersForQuestionRow
	for rows.Next() {
		var i ListAnswersForQuestionRow
		if err := rows.Scan(
			&i.ID,
			&i.QuestionID,
			&i.BodyMd,
			&i.BodyHtml,
			&i.AuthorUserID,
			&i.SourceID,
			&i.SourcePostID,
			&i.SourceUrl,
			&i.ImportedAuthorID,
			&i.ImportedScore,
			&i.LocalScore,
			&i.LocallyModified,
			&i.NeedsReview,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.EditedAt,
			&i.LastEditorUserID,
			&i.EditCount,
			&i.TotalScore,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

